\begin{axis}[axis x line=bottom, axis y line=left, xlabel={Workers $n$}, ylabel={Time $t$ (days)}, xmin=0, xmax=10, ymin=0, ymax=32, domain=2:10, samples=100, restrict y to domain=0:32, unbounded coords=jump]
